1	// A discrete-event simulator of the tasks-dispatch spec (DESIGN.md), so the
2	// scenario play-throughs in SCENARIOS.md are executable instead of prose-only.
3	//
4	// What it models faithfully: virtual time, the tick's three jobs (calendar-only
5	// instantiation with both guards and the first-item rule, readiness, the
6	// executing-leash reclaim), the executor loop (pick order, same-title mutex,
7	// the `after` yield, claim, validate, the single precondition evaluation, the
8	// roll, prework/hand-off/converge as timed phases), the janitor's stale-ready
9	// escalation, and the force-is-waking lever. `afterMode: 'blocked-by'` exists
10	// solely so S24 can demonstrate the starvation that ruled that wiring out.
11	//
12	// What it deliberately does NOT model is inventoried in README.md's "The
13	// unsimulated world" — one row per boundary (cron delivery, list freshness,
14	// label non-atomicity, comment-id ordering, event delivery, secrets, …) with
15	// what defends the design there. A bug living exactly on one of those
16	// boundaries will not surface here; executor contention IS modeled, as
17	// stale-snapshot races over the claim protocol (raceExecutorsAt).
18	//
19	// Time is milliseconds UTC; events run strictly in time order (FIFO within a
20	// tie). Nothing here sleeps, threads, or reads the wall clock.
21	
22	const MIN = 60_000;
23	const HOUR = 60 * MIN;
24	const DAY = 24 * HOUR;
25	
26	export const T = (iso) => Date.parse(iso.length === 17 ? iso.replace('Z', ':00Z') : iso);
27	const iso = (t) => new Date(t).toISOString().slice(0, 16) + 'Z';
28	
29	// ---- frequency → anchors ----------------------------------------------------
30	// daily-Nh anchors at N:00Z, plain daily at 04:00Z, hourly at :00, weekly at
31	// Sunday 04:00Z. mostRecentAnchor is the latest anchor ≤ now; nextAnchor the
32	// earliest one > now.
33	
34	// daily-Nh / daily+Nh offset the schedule's daily hour (default 4), per the
35	// engine's DAILY_OFFSETS: daily-2h → 02:00Z, daily-1h → 03:00Z, daily → 04:00Z.
36	function anchorHour(frequency) {
37	  const m = /^daily([+-]\d+)h$/.exec(frequency);
38	  if (m) return 4 + Number(m[1]);
39	  if (frequency === 'daily') return 4;
40	  if (frequency === 'weekly') return 4;
41	  throw new Error(`no anchor hour for ${frequency}`);
42	}
43	
44	export function periodMs(frequency) {
45	  if (frequency === 'hourly') return HOUR;
46	  if (frequency === 'weekly') return 7 * DAY;
47	  return DAY; // daily, daily-Nh
48	}
49	
50	export function mostRecentAnchor(frequency, now) {
51	  if (frequency === 'manual') return null;
52	  if (frequency === 'hourly') return Math.floor(now / HOUR) * HOUR;
53	  const d = new Date(now);
54	  let a = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), anchorHour(frequency));
55	  if (a > now) a -= DAY;
56	  if (frequency === 'weekly') {
57	    while (new Date(a).getUTCDay() !== 0 || a > now) a -= DAY;
58	  }
59	  return a;
60	}
61	
62	export function nextAnchor(frequency, now) {
63	  let a = mostRecentAnchor(frequency, now);
64	  do a += periodMs(frequency); while (a <= now);
65	  return a;
66	}
67	
68	// ---- the simulator ----------------------------------------------------------
69	
70	export function makeSim({
71	  tasks,
72	  afterMode = 'yield', // 'yield' (the design) | 'blocked-by' (S24's rejected wiring)
73	  tickMinute = 17,
74	  executingLeashMs = 1 * HOUR,
75	  agentLeashMs = 3 * HOUR,
76	  staleReadyPeriods = 2,
77	  staleBlockedMs = 2 * DAY,
78	  unsafeLeash = false, // S31 only: bypass the F17 wiring constraint
79	} = {}) {
80	  const registry = new Map(tasks.map((t) => [t.id, t]));
81	  const titleOf = (id) => `[claudinite-work] ${id}`;
82	
83	  // F17's wiring-time constraint: a prework that can legally outlive the
84	  // executing leash would be reclaimed while alive — duplicate prework runs.
85	  // The real engine enforces leash > prework-timeout as a conformance check;
86	  // the sim enforces it at construction. `unsafeLeash` exists only so S31
87	  // can demonstrate the hazard the constraint prevents.
88	  if (!unsafeLeash) {
89	    for (const t of tasks) {
90	      if ((t.preworkMinutes ?? 1) * MIN >= executingLeashMs) {
91	        throw new Error(
92	          `task ${t.id}: prework bound (${t.preworkMinutes}m) reaches the executing leash — F17`);
93	      }
94	    }
95	  }
96	
97	  const issues = []; // {number,title,taskId,origin,labels:Set,state,createdAt,closedAt,readySince,lastActivity,notBefore,blockedBy:[],outcome,rolls:[],comments:[],escalated,sessions:[],agentClaims:[],handoffAttempts,quarantined}
98	  const log = []; // {t,kind,task,issue,...}
99	  const world = {}; // scenario-owned signal state, read by precondition fns
100	  const queue = []; // {t,seq,fn}
101	  let seq = 0;
102	  let now = 0;
103	  let sessionSeq = 0;
104	  const crashNextOf = new Set(); // taskIds whose next execution dies mid-claim
105	  const crashAgentOf = new Set(); // taskIds whose next agent session dies mid-run
106	
107	  const schedule = (t, fn) => queue.push({ t, seq: seq++, fn });
108	  const record = (kind, extra) => log.push({ t: now, at: iso(now), kind, ...extra });
109	
110	  const open = () => issues.filter((i) => i.state === 'open');
111	  const has = (i, l) => i.labels.has(l);
112	  const family = (taskId) =>
113	    issues.filter((i) => i.title === titleOf(taskId) && i.origin === 'schedule');
114	  const standingItem = (taskId) => family(taskId).find((i) => i.state === 'open');
115	
116	  function createIssue({ taskId, origin, labels, notBefore = null, blockedBy = [], urgent = false, qualifier = null }) {
117	    const it = {
118	      number: issues.length + 900,
119	      title: titleOf(taskId) + (qualifier ? ` ${qualifier}` : ''),
120	      taskId, origin,
121	      labels: new Set(labels.concat(urgent ? ['task:urgent'] : [])),
122	      state: 'open',
123	      createdAt: now, closedAt: null,
124	      readySince: labels.includes('task:ready') ? now : null,
125	      lastActivity: now,
126	      notBefore, blockedBy,
127	      outcome: null, rolls: [], comments: [], escalated: false,
128	      sessions: [], agentClaims: [], handoffAttempts: 0, quarantined: false,
129	    };
130	    issues.push(it);
131	    record('create', { task: taskId, issue: it.number, origin });
132	    return it;
133	  }
134	
135	  function swap(it, from, to) {
136	    it.labels.delete(from);
137	    it.labels.add(to);
138	    it.readySince = to === 'task:ready' ? now : null;
139	    // F18: every transition INTO ready opens a new claim episode — claim
140	    // comments from a previous tenure are dead and must not outrank a live
141	    // claimant (the revert/reclaim comment is the episode boundary)
142	    if (to === 'task:ready') it.claimEpoch = seq++;
143	    it.lastActivity = now;
144	  }
145	
146	  function close(it, outcome) {
147	    it.state = 'closed';
148	    it.closedAt = now;
149	    it.outcome = outcome;
150	    for (const l of [...it.labels]) if (l.startsWith('task:')) it.labels.delete(l);
151	    record('close', { task: it.taskId, issue: it.number, outcome });
152	  }
153	
154	  // ---- the tick (DESIGN §5): pure function of the clock and the issue list --
155	  function tick() {
156	    record('tick', {});
157	    // job 1: instantiate — calendar-only, no preconditions, no signals
158	    for (const task of registry.values()) {
159	      if (task.frequency === 'manual') continue;
160	      const A = mostRecentAnchor(task.frequency, now);
161	      const fam = family(task.id);
162	      // F16 self-heal: if a stale issue list ever let a duplicate standing
163	      // item through (nothing guarantees a REST list from another node sees a
164	      // creation seconds old), close every open one but the oldest. The tick
165	      // is serialized (concurrency group), so this cannot race itself.
166	      const openFam = fam.filter((i) => i.state === 'open')
167	        .sort((a, b) => a.number - b.number);
168	      for (const dup of openFam.slice(1)) {
169	        close(dup, 'obsolete');
170	        record('dedupe', { task: task.id, issue: dup.number });
171	      }
172	      if (openFam.length > 0) continue; // standing item exists
173	      // occurrence guard, both halves (F13): an item CREATED at-or-after A
174	      // covers this occurrence — and so does an item CLOSED at-or-after A,
175	      // because a rolled item created in an earlier period that ran today
176	      // consumed today's occurrence. Creation-time alone double-executes.
177	      if (fam.some((i) => i.createdAt >= A || (i.closedAt ?? -Infinity) >= A)) continue;
178	      const firstEver = fam.length === 0;
179	      const blockedByUp =
180	        afterMode === 'blocked-by'
181	          ? (task.after ?? []).map((up) => standingItem(up)?.number).filter(Boolean)
182	          : [];
183	      const born = firstEver || blockedByUp.length > 0 ? 'task:blocked' : 'task:ready';
184	      createIssue({
185	        taskId: task.id, origin: 'schedule',
186	        labels: ['origin:schedule', born],
187	        notBefore: firstEver ? nextAnchor(task.frequency, now) : null,
188	        blockedBy: blockedByUp,
189	      });
190	    }
191	    // job 2: ready whatever is due
192	    for (const it of open().filter((i) => has(i, 'task:blocked'))) {
193	      const blockersDone = it.blockedBy.every(
194	        (n) => issues.find((x) => x.number === n)?.state === 'closed'
195	      );
196	      if (blockersDone && (it.notBefore === null || now >= it.notBefore)) {
197	        swap(it, 'task:blocked', 'task:ready');
198	        record('ready', { task: it.taskId, issue: it.number });
199	      }
200	    }
201	    // job 3: reclaim dead executor claims
202	    for (const it of open().filter((i) => has(i, 'task:executing'))) {
203	      if (now - it.lastActivity >= executingLeashMs) {
204	        swap(it, 'task:executing', 'task:ready');
205	        it.comments.push({ t: now, body: 'reclaimed: executor went silent past the leash' });
206	        record('reclaim', { task: it.taskId, issue: it.number });
207	      }
208	    }
209	  }
210	
211	  // ---- the executor (DESIGN §6) ---------------------------------------------
212	  function pickable() {
213	    const ready = open().filter((i) => has(i, 'task:ready'));
214	    const live = (taskId) => {
215	      const s = standingItem(taskId);
216	      return s && ['task:ready', 'task:executing', 'task:agent'].some((l) => has(s, l));
217	    };
218	    return ready
219	      .filter((i) => !i.quarantined) // an item no live executor can reach (S18)
220	      .filter((i) => {
221	        // same-title mutex: one task, one execution at a time
222	        if (open().some((o) => o !== i && o.title === i.title &&
223	              (has(o, 'task:executing') || has(o, 'task:agent')))) return false;
224	        // the `after` yield: skip while the upstream's standing item is live
225	        // this cycle (a rolled or needs-human upstream does not block — S23)
226	        if (afterMode === 'yield' && i.origin === 'schedule') {
227	          const ups = registry.get(i.taskId)?.after ?? [];
228	          if (ups.some((up) => live(up))) return false;
229	        }
230	        return true;
231	      })
232	      .sort((a, b) =>
233	        (has(b, 'task:urgent') ? 1 : 0) - (has(a, 'task:urgent') ? 1 : 0) ||
234	        a.createdAt - b.createdAt || a.number - b.number);
235	  }
236	
237	  // The claim is the verified lease (DESIGN §6.2): swap, post a claim
238	  // comment, re-read — earliest comment wins, the loser reverts nothing and
239	  // moves on. `preRead` is the label state the executor saw when it read the
240	  // item; a racing executor's stale read is modeled by passing the snapshot
241	  // taken before the rival's swap landed.
242	  function claim(it, execId, preRead) {
243	    if (!preRead.has('task:ready') || preRead.has('needs-human') ||
244	        preRead.has('task:executing') || preRead.has('task:agent')) return false;
245	    it.labels.delete('task:ready');
246	    it.labels.add('task:executing');
247	    it.readySince = null;
248	    it.lastActivity = now;
249	    it.comments.push({ t: now, seq: seq++, kind: 'claim', exec: execId });
250	    // F18: arbitrate only among THIS episode's claims — earliest since the
251	    // item last became ready, by server-assigned comment order
252	    const claims = it.comments.filter((c) => c.kind === 'claim' && c.seq > (it.claimEpoch ?? -1));
253	    const won = claims[0].exec === execId;
254	    record(won ? 'claim' : 'claim-lost', { task: it.taskId, issue: it.number, exec: execId });
255	    return won; // loser reverts nothing — the winner's labels already stand
256	  }
257	
258	  // Hand-off + invocation (DESIGN §6.6): swap to task:agent, then call the
259	  // API. Failure after in-run retries reverts to task:ready with an attempt
260	  // counter (F3); at 5 attempts the item converges needs-human. A client
261	  // timeout that still created a session makes invocation at-least-once
262	  // (S10): the retry spawns a second session, and the agent-side lease (F5,
263	  // DESIGN §7) — earliest agent claim comment wins — collapses the pair.
264	  function handOff(it, task) {
265	    swap(it, 'task:executing', 'task:agent');
266	    if (world._apiDownUntil != null && now < world._apiDownUntil) {
267	      it.handoffAttempts += 1;
268	      record('handoff-failed', { task: it.taskId, issue: it.number, attempts: it.handoffAttempts });
269	      if (it.handoffAttempts >= 5) {
270	        swap(it, 'task:agent', 'needs-human');
271	        record('handoff-exhausted', { task: it.taskId, issue: it.number });
272	      } else {
273	        swap(it, 'task:agent', 'task:ready'); // bounded revert; tick cadence is the backoff
274	      }
275	      return;
276	    }
277	    record('handoff', { task: it.taskId, issue: it.number });
278	    const spawn = () => {
279	      const s = { id: `s-${++sessionSeq}`, item: it.number };
280	      it.sessions.push(s);
281	      schedule(now + 30_000, () => startAgentSession(s, it, task));
282	    };
283	    spawn();
284	    if (world._apiTimeoutOnce) { // the call timed out client-side but landed
285	      world._apiTimeoutOnce = false;
286	      record('invoke-retry-duplicate', { task: it.taskId, issue: it.number });
287	      spawn(); // the retry creates the second session
288	    }
289	  }
290	
291	  function startAgentSession(s, it, task) {
292	    if (it.state !== 'open' || !has(it, 'task:agent')) return;
293	    it.agentClaims.push(s); // the agent-side lease: claim comment, re-read
294	    if (it.agentClaims[0] !== s) {
295	      record('agent-lease-lost', { task: it.taskId, issue: it.number, session: s.id });
296	      return; // the loser stops without touching the item (F5)
297	    }
298	    it.lastActivity = now;
299	    if (crashAgentOf.delete(it.taskId)) {
300	      record('agent-died', { task: it.taskId, issue: it.number, session: s.id });
301	      return; // never converges; the janitor's agent leash is the recovery (S11)
302	    }
303	    schedule(now + task.agentMinutes * MIN, () => {
304	      if (it.state !== 'open') return;
305	      if (task.agentFails?.(world, now)) {
306	        swap(it, 'task:agent', 'needs-human');
307	        record('agent-failed', { task: it.taskId, issue: it.number });
308	        return;
309	      }
310	      close(it, task.outcome ?? 'done');
311	    });
312	  }
313	
314	  function executeClaimed(it, task) {
315	    if (crashNextOf.delete(it.taskId)) {
316	      record('executor-crash', { task: it.taskId, issue: it.number });
317	      return false; // died mid-claim: labels stay, the leash reclaim recovers (S8)
318	    }
319	    // the single precondition evaluation (DESIGN §6.4)
320	    const verdict = task.precondition ? task.precondition(world, now) : { run: true };
321	    record('evaluate', { task: it.taskId, issue: it.number, run: verdict.run !== false });
322	    if (verdict.run === false) {
323	      if (it.origin === 'schedule') { // roll
324	        it.notBefore = nextAnchor(task.frequency, now);
325	        it.rolls.push({ t: now, reason: verdict.reason ?? 'no work' });
326	        swap(it, 'task:executing', 'task:blocked');
327	        record('roll', { task: it.taskId, issue: it.number, until: iso(it.notBefore) });
328	      } else {
329	        close(it, 'obsolete'); // ad-hoc: no anchor to roll to (S17)
330	      }
331	      return true;
332	    }
333	    // prework → optional hand-off → converge, as timed phases. The executor
334	    // re-verifies its OWN lease at the transition (F17): not just "is the
335	    // item executing" but "is my claim still the newest" — a reclaim-then-
336	    // re-pick puts a newer claim on the item, and the stale runner must see
337	    // it and abandon silently rather than hand off work it no longer owns.
338	    const myClaim = it.comments.filter((c) => c.kind === 'claim').at(-1);
339	    schedule(now + (task.preworkMinutes ?? 1) * MIN, () => {
340	      if (it.state !== 'open' || !has(it, 'task:executing')) return;
341	      if (it.comments.filter((c) => c.kind === 'claim').at(-1) !== myClaim) return;
342	      it.lastActivity = now;
343	      if (task.preworkFails?.(world, now)) {
344	        swap(it, 'task:executing', 'needs-human');
345	        record('prework-failed', { task: it.taskId, issue: it.number });
346	        return;
347	      }
348	      const wantsAgent = task.agentMinutes != null &&
349	        (task.requestsAgent ? task.requestsAgent(world, now) : true);
350	      if (!wantsAgent) { close(it, task.outcome ?? 'done'); return; }
351	      handOff(it, task);
352	    });
353	    return true;
354	  }
355	
356	  // F15: the pick filters (same-title mutex, `after` yield) are read from
357	  // possibly-stale state, so two executors can pass them simultaneously and
358	  // claim DIFFERENT items that the filters should have serialized — a twin
359	  // pair, or an upstream and its dependent. The lease protects one item, not
360	  // one title. So after WINNING a claim, re-verify the filters against live
361	  // state: if a conflicting item now holds an EARLIER claim (comment order —
362	  // the same arbiter the lease trusts), revert this claim to task:ready and
363	  // move on. Bounded (one revert), deterministic (comment order), and the
364	  // earlier claim never even notices.
365	  function postClaimVerify(it, execId) {
366	    const myClaim = it.comments.filter((c) => c.kind === 'claim').at(-1);
367	    const conflicts = open().filter((o) => {
368	      if (o === it) return false;
369	      const live = has(o, 'task:executing') || has(o, 'task:agent');
370	      if (!live) return false;
371	      if (o.title === it.title) return true; // twin
372	      if (afterMode === 'yield' && it.origin === 'schedule') {
373	        const ups = registry.get(it.taskId)?.after ?? [];
374	        if (ups.some((up) => o.title === titleOf(up) && o.origin === 'schedule')) return true;
375	      }
376	      return false;
377	    });
378	    const earlier = conflicts.some((o) =>
379	      o.comments.filter((c) => c.kind === 'claim').at(-1)?.seq < myClaim.seq);
380	    if (!earlier) return true;
381	    swap(it, 'task:executing', 'task:ready');
382	    record('claim-reverted', { task: it.taskId, issue: it.number, exec: execId });
383	    return false;
384	  }
385	
386	  function executorRun(execId = 'E1') {
387	    for (let i = 0; i < 10; i++) {
388	      const it = pickable()[0];
389	      if (!it) return;
390	      if (!claim(it, execId, new Set(it.labels))) continue;
391	      if (!postClaimVerify(it, execId)) continue;
392	      const task = registry.get(it.taskId);
393	      if (!task) { close(it, 'obsolete'); continue; } // validate: task gone (S20)
394	      if (!executeClaimed(it, task)) return;
395	    }
396	  }
397	
398	  // ---- the janitor (DESIGN §11): the judgment-and-long-horizon sweeps -------
399	  function janitor() {
400	    // rule A — stale-ready: an item no executor picked for ~2 periods comes
401	    // out of the queue as a human's problem (S18's stuck member)
402	    for (const it of open().filter((i) => has(i, 'task:ready') && !i.escalated)) {
403	      const per = registry.has(it.taskId) ? periodMs(registry.get(it.taskId).frequency) : DAY;
404	      if (it.readySince !== null && now - it.readySince >= staleReadyPeriods * per) {
405	        it.escalated = true;
406	        swap(it, 'task:ready', 'needs-human');
407	        record('escalate', { task: it.taskId, issue: it.number, rule: 'stale-ready' });
408	      }
409	    }
410	    // rule B — the agent leash: task:agent silent past ~3h means the session
411	    // died; converge needs-human, naming the dead session (S11)
412	    for (const it of open().filter((i) => has(i, 'task:agent'))) {
413	      if (now - it.lastActivity >= agentLeashMs) {
414	        const dead = it.agentClaims[0]?.id ?? it.sessions.at(-1)?.id ?? 'unknown';
415	        swap(it, 'task:agent', 'needs-human');
416	        it.comments.push({ t: now, body: `agent session ${dead} went silent past the leash` });
417	        record('agent-reclaim', { task: it.taskId, issue: it.number, session: dead });
418	      }
419	    }
420	    // rule C — stuck dependency (F14): a blocked item whose blockers have not
421	    // resolved for ~2 days is surfaced with an escalation COMMENT — labels
422	    // stay untouched, so the item still proceeds by itself the moment its
423	    // blockers resolve. Sleeping items (future Not-before, blockers closed)
424	    // and rolling items (no blockers) never match.
425	    for (const it of open().filter((i) => has(i, 'task:blocked') && !i.escalated)) {
426	      const blocked = it.blockedBy.some((n) => issues.find((x) => x.number === n)?.state !== 'closed');
427	      if (blocked && now - it.createdAt >= staleBlockedMs) {
428	        it.escalated = true;
429	        it.comments.push({ t: now, body: 'stuck: blockers unresolved past the bound' });
430	        record('escalate', { task: it.taskId, issue: it.number, rule: 'stuck-dependency' });
431	      }
432	    }
433	  }
434	
435	  // ---- the scenario DSL -----------------------------------------------------
436	  const droppedTicks = [];
437	  const sim = {
438	    issues, log, world,
439	    family, standingItem,
440	
441	    // "at time X, Y happens"
442	    at(isoTime, fn) { schedule(T(isoTime), () => fn(sim)); return sim; },
443	
444	    // GitHub drops scheduled fires in [from, to) — the ticks simply don't run
445	    dropTicks(fromIso, toIso) { droppedTicks.push([T(fromIso), T(toIso)]); return sim; },
446	    // one late/manual tick outside the cron grid (with its post-tick drain)
447	    tickAt(isoTime) {
448	      schedule(T(isoTime), tick);
449	      schedule(T(isoTime) + 40_000, executorRun);
450	      return sim;
451	    },
452	
453	    // an established repo: every scheduled task already ran its previous
454	    // occurrence (a closed done item), so the first-item rule doesn't apply
455	    seedSteadyState(asOfIso) {
456	      const t0 = T(asOfIso);
457	      for (const task of registry.values()) {
458	        if (task.frequency === 'manual') continue;
459	        const a = mostRecentAnchor(task.frequency, t0);
460	        issues.push({
461	          number: issues.length + 800, title: titleOf(task.id), taskId: task.id,
462	          origin: 'schedule', labels: new Set(['origin:schedule']), state: 'closed',
463	          createdAt: a, closedAt: a + 30 * MIN, readySince: null, lastActivity: a,
464	          notBefore: null, blockedBy: [], outcome: 'done', rolls: [], comments: [],
465	          escalated: false, seeded: true,
466	        });
467	      }
468	      return sim;
469	    },
470	
471	    // forcing a scheduled task = waking its standing item (DESIGN §8)
472	    force(taskId, { urgent = true } = {}) {
473	      const it = standingItem(taskId);
474	      if (!it) throw new Error(`no standing item for ${taskId}`);
475	      it.notBefore = null;
476	      if (has(it, 'task:blocked')) swap(it, 'task:blocked', 'task:ready');
477	      if (has(it, 'needs-human')) { it.labels.delete('needs-human'); it.labels.add('task:ready'); it.readySince = now; it.claimEpoch = seq++; }
478	      if (urgent) it.labels.add('task:urgent');
479	      record('force', { task: taskId, issue: it.number });
480	      schedule(now + 1 * MIN, () => executorRun()); // the labeled event's latency sugar
481	      return it;
482	    },
483	
484	    // ad-hoc work is creating an item (DESIGN §8) — origin manual.
485	    // eventLost models a dropped `labeled` webhook (S16): no immediate
486	    // executor run fires; the next tick's drain is the guarantee.
487	    createItem(taskId, { urgent = false, notBefore = null, blockedBy = [], qualifier = null, eventLost = false } = {}) {
488	      const born = notBefore !== null || blockedBy.length ? 'task:blocked' : 'task:ready';
489	      const it = createIssue({ taskId, origin: 'manual', labels: [born], notBefore, blockedBy, urgent, qualifier });
490	      if (born === 'task:ready' && !eventLost) schedule(now + 1 * MIN, () => executorRun());
491	      return it;
492	    },
493	
494	    crashNextExecutionOf(taskId) { crashNextOf.add(taskId); return sim; },
495	    crashNextAgentOf(taskId) { crashAgentOf.add(taskId); return sim; },
496	
497	    // the task file disappears from HEAD (S20): validate-in-code closes obsolete
498	    removeTask(taskId) { registry.delete(taskId); return sim; },
499	
500	    // a declaration change lands at HEAD (S28): the very next tick/pick reads
501	    // the new frequency/after/precondition — items carry no schedule to migrate
502	    updateTask(taskId, patch) {
503	      registry.set(taskId, { ...registry.get(taskId), ...patch });
504	      return sim;
505	    },
506	
507	    // an issue from another mechanism/vocabulary (S29): present in the repo,
508	    // outside the [claudinite-work] family — the tick must never touch it
509	    foreignIssue(title) {
510	      const it = {
511	        number: issues.length + 700, title, taskId: null, origin: 'foreign',
512	        labels: new Set(['agent-dispatch']), state: 'open',
513	        createdAt: now, closedAt: null, readySince: null, lastActivity: now,
514	        notBefore: null, blockedBy: [], outcome: null, rolls: [], comments: [],
515	        escalated: false, sessions: [], agentClaims: [], handoffAttempts: 0,
516	        quarantined: false,
517	      };
518	      issues.push(it);
519	      return it;
520	    },
521	
522	    // ---- multi-executor contention (S7) ------------------------------------
523	    // Two executors read the SAME snapshot of the ready list, so both pick
524	    // the same first item; both swap and post claim comments; the earliest
525	    // comment wins and the loser moves on to the next item read from LIVE
526	    // state — the verified lease, stale-read and all (DESIGN §6.2).
527	    // spread: false (default) — both executors pick the SAME first item (S7's
528	    // one-item race). spread: true — executor i picks snapshot[i]: different
529	    // items, claimed simultaneously from the same stale read, which is how a
530	    // twin pair or an upstream+dependent slip past the pick filters together
531	    // (S32/F15) — only the post-claim re-verify serializes them.
532	    raceExecutorsAt(isoTime, execIds, { spread = false } = {}) {
533	      schedule(T(isoTime), () => {
534	        const snapshot = pickable();
535	        const preReads = new Map(snapshot.map((i) => [i, new Set(i.labels)]));
536	        const winners = [];
537	        execIds.forEach((execId, k) => {
538	          const target = spread ? snapshot[k] : snapshot[0];
539	          if (!target) return;
540	          if (claim(target, execId, preReads.get(target))) winners.push([target, execId]);
541	          else executorRun(execId); // same-item loser moves on, from live state
542	        });
543	        for (const [target, execId] of winners) {
544	          if (!postClaimVerify(target, execId)) continue;
545	          const task = registry.get(target.taskId);
546	          if (task) executeClaimed(target, task);
547	        }
548	      });
549	      return sim;
550	    },
551	
552	    // F16's precondition: a tick whose issue list was stale created a second
553	    // standing item. Injected directly — the sim's own tick can't produce it.
554	    injectDuplicateStanding(taskId) {
555	      return createIssue({ taskId, origin: 'schedule', labels: ['origin:schedule', 'task:ready'] });
556	    },
557	
558	    // ---- platform failure injection (S9/S10) -------------------------------
559	    apiDownUntil(isoTime) { world._apiDownUntil = T(isoTime); return sim; },
560	    apiTimeoutOnce() { world._apiTimeoutOnce = true; return sim; },
561	
562	    // ---- fleet / human levers ----------------------------------------------
563	    quarantine(number) { issues.find((i) => i.number === number).quarantined = true; return sim; },
564	    closeByHand(number, outcome = 'obsolete') {
565	      const it = issues.find((i) => i.number === number);
566	      it.state = 'closed'; it.closedAt = now; it.outcome = outcome;
567	      for (const l of [...it.labels]) if (l.startsWith('task:') || l === 'needs-human') it.labels.delete(l);
568	      record('close', { task: it.taskId, issue: it.number, outcome, by: 'hand' });
569	      return sim;
570	    },
571	    // the sanctioned human re-queue (F7, DESIGN §4): strip needs-human,
572	    // apply task:ready — the same lever forcing uses
573	    requeue(number) {
574	      const it = issues.find((i) => i.number === number);
575	      it.labels.delete('needs-human');
576	      it.labels.delete('task:blocked');
577	      it.notBefore = null;
578	      it.labels.add('task:ready');
579	      it.readySince = now;
580	      it.claimEpoch = seq++;
581	      it.lastActivity = now;
582	      record('requeue', { task: it.taskId, issue: it.number });
583	      schedule(now + 1 * MIN, () => executorRun());
584	      return sim;
585	    },
586	
587	    // run the clock: hourly ticks at :tickMinute (each with its post-tick
588	    // drain), a daily janitor, then drain the event queue strictly in order
589	    run(fromIso, toIso) {
590	      const from = T(fromIso), to = T(toIso);
591	      for (let t = Math.ceil(from / HOUR) * HOUR + tickMinute * MIN; t < to; t += HOUR) {
592	        if (t < from) continue;
593	        if (droppedTicks.some(([a, b]) => t >= a && t < b)) continue;
594	        schedule(t, tick);
595	        schedule(t + 40_000, executorRun);
596	      }
597	      for (let t = Math.ceil(from / DAY) * DAY + 4 * HOUR + 3 * MIN; t < to; t += DAY) {
598	        if (t >= from) schedule(t, janitor);
599	      }
600	      for (;;) {
601	        queue.sort((a, b) => a.t - b.t || a.seq - b.seq);
602	        const ev = queue.shift();
603	        if (!ev || ev.t >= to) break;
604	        now = ev.t;
605	        ev.fn();
606	      }
607	      now = to;
608	      return sim;
609	    },
610	  };
611	  return sim;
612	}
