60	const evals = (sim, task) => sim.log.filter((e) => e.kind === 'evaluate' && e.task === task);
61	const closedOf = (sim, task) =>
62	  sim.family(task).filter((i) => !i.seeded && i.state === 'closed' && i.outcome != null);
