64	// ---- S1' — quiet night: one evaluation per task per period, then everything
65	// sleeps as a blocked standing item wearing its next wake time.
66	test("S1' quiet night: one ask per period, items roll and sleep", () => {
67	  const sim = makeSim({ tasks: cast() })
68	    .seedSteadyState('2026-08-12T00:00Z')
69	    .run('2026-08-12T00:00Z', '2026-08-13T00:00Z');
70	
71	  for (const task of ['basics/baselining', 'tidy/tidy-issues', 'chrome/store-release']) {
72	    assert.equal(evals(sim, task).length, 1, `${task} asked once`);
73	    const it = sim.standingItem(task);
74	    assert.ok(it.labels.has('task:blocked'), `${task} sleeps`);
75	    assert.ok(it.notBefore > T('2026-08-12T23:59Z'), `${task} wakes tomorrow`);
