114	// ---- S4 — the late-fire night: all cron fires drop, one late tick at 05:41,
115	// and the chain still runs the same morning, in order, via the pick-time yield.
116	test('S4 late fire: the chain completes the same morning, ordered', () => {
117	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
118	  sim.at('2026-08-12T00:01Z', ({ world }) => {
119	    world.mountBehind = true;         // baselining has real work (no judgment needed)
120	    world.extractHasLessons = true;   // and so does the rest of the chain
121	    world.promoteHasCandidates = true;
122	  });
123	  sim.dropTicks('2026-08-12T00:00Z', '2026-08-12T05:41Z');
124	  sim.tickAt('2026-08-12T05:41Z');
125	  sim.run('2026-08-12T00:00Z', '2026-08-12T09:00Z');
126	
127	  const [base] = closedOf(sim, 'basics/baselining');
128	  const [extract] = closedOf(sim, 'grow/growth-extract');
129	  const [promote] = closedOf(sim, 'grow/growth-promote');
130	  assert.ok(base && extract && promote, 'all three converged');
131	  assert.ok(base.closedAt < extract.closedAt, 'baselining before extract');
132	  assert.ok(extract.closedAt < promote.closedAt, 'extract before promote');
133	  assert.ok(promote.closedAt < T('2026-08-12T09:00Z'), 'same morning, not tomorrow');
134	  // extract was never picked while baselining was live
135	  const baseClaim = sim.log.find((e) => e.kind === 'evaluate' && e.task === 'basics/baselining');
136	  const extractClaim = sim.log.find((e) => e.kind === 'evaluate' && e.task === 'grow/growth-extract');
137	  assert.ok(extractClaim.t >= base.closedAt, 'yield held while upstream ran');
138	  assert.ok(baseClaim.t >= T('2026-08-12T05:41Z'), 'nothing happened before the late tick');
139	});
