142	// first tick back; exactly one catch-up ask per task, no backfill.
143	test('S5 three-day outage: one catch-up ask, no backfill', () => {
144	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-11T00:00Z');
