553	  sim.at('2026-08-12T00:01Z', ({ world }) => { world.mountBehind = true; world.mountBroken = true; });
554	  // Tuesday: the owner fixes the mount and re-queues via the force lever
555	  sim.at('2026-08-13T09:00Z', (s) => { s.world.mountBroken = false; s.force('basics/baselining', { urgent: false }); });
556	  sim.run('2026-08-12T00:00Z', '2026-08-13T12:00Z');
557	
558	  const it = sim.family('basics/baselining').find((i) => !i.seeded);
559	  assert.equal(it.state, 'closed');
560	  assert.equal(it.outcome, 'done', 'the same item converged after the fix — no new item was ever needed');
561	  assert.equal(sim.family('basics/baselining').filter((i) => !i.seeded).length, 1);
562	});
563	
564	// ---- S26 — the guard's second half must not over-block either: after a
565	// rolled item runs and closes, the NEXT period still gets a fresh item.
566	test('S26b the closed-at guard half releases at the next anchor', () => {
567	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
568	  sim.at('2026-08-12T09:03Z', ({ world }) => { world.issueTouchedAt = T('2026-08-12T09:03Z'); });
569	  sim.run('2026-08-12T00:00Z', '2026-08-14T12:00Z');
570	
571	  // Wednesday's item rolls, runs Thursday 04:17, closes 04:34. The closed-at
572	  // guard half must suppress only THURSDAY's re-creation — Friday's anchor
573	  // must still get a fresh item.
574	  const fam = sim.family('tidy/tidy-issues').filter((i) => !i.seeded);
575	  assert.equal(closedOf(sim, 'tidy/tidy-issues').length, 1, 'Thursday ran once, not twice');
576	  assert.equal(fam.length, 2, "the Wednesday item (closed Thursday) plus Friday's fresh item");
577	  assert.ok(fam[1].createdAt >= T('2026-08-14T04:00Z'),
578	    "Friday's occurrence was not eaten by Thursday's close");
579	});
580	
581	// ---- S28 — the mechanism (or a task) changes mid-flight: items carry no
582	// schedule, so a declaration change applies at the very next evaluation with
583	// no migration and no relabeling.
584	test('S28 declaration change mid-flight: the standing item follows HEAD', () => {
585	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
586	  // mid-day, an update lands: tidy-issues moves to the 02:00 anchor and now
587	  // yields to baselining; its precondition is replaced outright
588	  sim.at('2026-08-12T12:00Z', (s) => s.updateTask('tidy/tidy-issues', {
589	    frequency: 'daily-2h',
590	    precondition: (w) => ({ run: !!w.newSignal, reason: 'new precondition, no work' }),
591	  }));
592	  sim.at('2026-08-14T01:00Z', ({ world }) => { world.newSignal = true; });
593	  sim.run('2026-08-12T00:00Z', '2026-08-14T12:00Z');
594	
595	  const it = sim.family('tidy/tidy-issues').find((i) => !i.seeded);
596	  const asks = evals(sim, 'tidy/tidy-issues');
597	  // day 2: the item sleeps out its ALREADY-STAMPED wake (old 04:00 anchor) —
598	  // the one scheduling fact it carries — and is judged there by the NEW
599	  // precondition; the update itself never touched the item
600	  assert.ok(asks[1].t >= T('2026-08-13T04:00Z') && asks[1].t < T('2026-08-13T05:00Z'),
601	    'second ask at the wake stamped before the update');
602	  assert.equal(asks[1].run, false, 'judged by the new precondition');
603	  assert.equal(it.rolls[1].reason, 'new precondition, no work');
604	  // and THAT roll targets the NEW anchor: day 3's ask lands at 02:17
605	  assert.ok(asks[2].t >= T('2026-08-14T02:00Z') && asks[2].t < T('2026-08-14T03:00Z'),
606	    'the first roll after the update adopts the new cadence');
607	  assert.equal(asks[2].run, true);
608	  assert.equal(it.state, 'closed', 'and ran under the new declaration');
609	});
610	
611	// ---- S29 — bootstrap into a repo with old-mechanism issues: the disjoint
612	// title family means the tick neither reads nor touches them.
613	test('S29 old-vocabulary issues are invisible to the new mechanism', () => {
614	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
615	  let relic;
616	  sim.at('2026-08-12T00:05Z', (s) => {
617	    relic = s.foreignIssue('[claudinite-task] basics/baselining d2026-08-11');
618	  });
619	  sim.run('2026-08-12T00:00Z', '2026-08-13T00:00Z');
620	
621	  assert.equal(relic.state, 'open', 'the relic is untouched');
622	  assert.deepEqual([...relic.labels], ['agent-dispatch'], 'no label was added or removed');
623	  assert.equal(relic.comments.length, 0);
624	  const it = sim.standingItem('basics/baselining');
625	  assert.ok(it && it.labels.has('task:blocked'),
626	    'the new mechanism ran its own item beside the relic, undisturbed');
627	});
628	
629	// ---- S30 — a stale issue list let a duplicate standing item through (F16):
630	// nothing documents REST-list read-your-writes across runs, so the design
631	// self-heals instead of assuming — the next tick closes every open standing
632	// item but the oldest.
633	test('S30 duplicate standing item: the next tick self-heals (F16)', () => {
634	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
635	  let dup;
636	  sim.at('2026-08-12T04:30Z', (s) => { dup = s.injectDuplicateStanding('tidy/tidy-issues'); });
637	  sim.run('2026-08-12T00:00Z', '2026-08-12T08:00Z');
638	
639	  assert.equal(dup.state, 'closed');
640	  assert.equal(dup.outcome, 'obsolete');
641	  assert.ok(sim.log.some((e) => e.kind === 'dedupe' && e.issue === dup.number));
642	  const openFam = sim.family('tidy/tidy-issues').filter((i) => i.state === 'open');
643	  assert.equal(openFam.length, 1, 'exactly one standing item survives');
644	  assert.ok(openFam[0].number < dup.number, 'and it is the oldest');
645	});
646	
647	// ---- S31 — the leash arithmetic (F17): a prework bound that reaches the
648	// executing leash is a wiring error, refused at wiring time — because run
649	// unsafe, a live prework gets reclaimed and its occurrence executes prework
650	// twice (the transition re-verify still keeps the hand-off single).
651	test('S31 prework bound >= executing leash is refused at wiring (F17)', () => {
652	  assert.throws(
653	    () => makeSim({ tasks: [{ id: 'x/slow', frequency: 'daily', preworkMinutes: 90 }] }),
654	    /reaches the executing leash — F17/);
655	});
656	
657	test('S31b the hazard the constraint prevents: live prework reclaimed, run twice', () => {
658	  const tasks = [{
659	    id: 'x/slow', frequency: 'daily', outcome: 'done', preworkMinutes: 130, // > 1h leash
660	    precondition: () => ({ run: true }),
661	  }];
662	  const sim = makeSim({ tasks, unsafeLeash: true }).seedSteadyState('2026-08-12T00:00Z');
663	  sim.run('2026-08-12T00:00Z', '2026-08-12T12:00Z');
664	
665	  // worse than duplicate prework — a LIVELOCK: every run is reclaimed before
666	  // it can finish, prework re-executes each cycle, and nothing ever converges
667	  assert.ok(sim.log.filter((e) => e.kind === 'reclaim').length >= 3, 'reclaimed again and again');
668	  assert.ok(evals(sim, 'x/slow').length >= 3, 'prework re-executed each cycle');
669	  assert.equal(closedOf(sim, 'x/slow').length, 0, 'and the occurrence NEVER converges');
670	});
671	
672	// ---- S32 — the pick-filter race (F15): two executors, same stale snapshot,
673	// each claims a DIFFERENT item of the same title. The per-item lease cannot
674	// see it; only the post-claim re-verify serializes the pair.
675	test('S32 twin-title race: post-claim re-verify serializes, later claim reverts', () => {
676	  // scoped cast: the scenario is about one title's twins racing
677	  const tasks = cast().filter((t) => t.id === 'tidy/tidy-issues');
678	  const sim = makeSim({ tasks }).seedSteadyState('2026-08-12T00:00Z');
679	  sim.at('2026-08-12T04:00Z', ({ world }) => { world.issueTouchedAt = T('2026-08-12T04:00Z'); });
680	  sim.dropTicks('2026-08-12T04:00Z', '2026-08-12T05:00Z');
681	  sim.tickAt('2026-08-12T04:16Z'); // scheduled item exists ready…
682	  sim.at('2026-08-12T04:16:20Z', (s) =>
683	    s.createItem('tidy/tidy-issues', { urgent: true, eventLost: true })); // …and its twin
684	  sim.raceExecutorsAt('2026-08-12T04:16:35Z', ['E1', 'E2'], { spread: true }); // before the drain
685	  sim.run('2026-08-12T00:00Z', '2026-08-12T12:00Z');
686	
687	  const reverts = sim.log.filter((e) => e.kind === 'claim-reverted');
688	  assert.equal(reverts.length, 1, 'exactly one of the two simultaneous claims reverted');
689	  // no instant ever had two same-title items in execution
690	  const twinEvals = sim.log.filter((e) => e.kind === 'evaluate' && e.task === 'tidy/tidy-issues');
691	  const times = twinEvals.map((e) => e.t);
692	  assert.equal(new Set(times).size, times.length, 'the twins were never evaluated at the same instant');
693	  // and BOTH still converged — the reverted one was re-claimed in a fresh
694	  // episode (F18: dead claims from the reverted tenure must not outrank the
695	  // next live claimant) and simply waited its turn
696	  for (const it of sim.issues.filter((i) => !i.seeded)) {
697	    assert.equal(it.state, 'closed', `#${it.number} converged`);
698	  }
699	});
700

