test('S31d dead executor mid-long-work: recovery is bounded by the leash, not the work', () => {
  const tasks = [{
    id: 'x/slow', frequency: 'daily', outcome: 'done', preworkMinutes: 130,
    precondition: () => ({ run: true }),
