1	// A discrete-event simulator of the tasks-dispatch spec (DESIGN.md), so the
2	// scenario play-throughs in SCENARIOS.md are executable instead of prose-only.
3	//
4	// What it models faithfully: virtual time, the tick's three jobs (calendar-only
5	// instantiation with both guards and the first-item rule, readiness, the
6	// executing-leash reclaim), the executor loop (pick order, same-title mutex,
7	// the `after` yield, claim, validate, the single precondition evaluation, the
8	// roll, the work step/hand-off/converge as timed phases, heartbeat comments
9	// during the work step so the leash measures executor death rather than work
10	// duration), at-most-once invocation (one call per item, never retried — the
11	// fired/refused/unanswered trichotomy of DESIGN §6.6), the readiness re-check
12	// on close (F1, reopened 2026-08-15), the janitor's stale-ready escalation,
13	// and the force-is-waking lever. `afterMode: 'blocked-by'` exists solely so
14	// S24 can demonstrate the starvation that ruled that wiring out.
15	//
16	// What it deliberately does NOT model is inventoried in README.md's "The
17	// unsimulated world" — one row per boundary (cron delivery, list freshness,
18	// label non-atomicity, comment-id ordering, event delivery, secrets, …) with
19	// what defends the design there. A bug living exactly on one of those
20	// boundaries will not surface here; executor contention IS modeled, as
21	// stale-snapshot races over the claim protocol (raceExecutorsAt).
22	//
23	// Time is milliseconds UTC; events run strictly in time order (FIFO within a
24	// tie). Nothing here sleeps, threads, or reads the wall clock.
25	
26	const MIN = 60_000;
27	const HOUR = 60 * MIN;
28	const DAY = 24 * HOUR;
29	
30	export const T = (iso) => Date.parse(iso.length === 17 ? iso.replace('Z', ':00Z') : iso);
31	const iso = (t) => new Date(t).toISOString().slice(0, 16) + 'Z';
32	
33	// ---- frequency → anchors ----------------------------------------------------
34	// daily-Nh anchors at N:00Z, plain daily at 04:00Z, hourly at :00, weekly at
35	// Sunday 04:00Z. mostRecentAnchor is the latest anchor ≤ now; nextAnchor the
36	// earliest one > now.
37	
38	// daily-Nh / daily+Nh offset the schedule's daily hour (default 4), per the
39	// engine's DAILY_OFFSETS: daily-2h → 02:00Z, daily-1h → 03:00Z, daily → 04:00Z.
40	function anchorHour(frequency) {
41	  const m = /^daily([+-]\d+)h$/.exec(frequency);
42	  if (m) return 4 + Number(m[1]);
43	  if (frequency === 'daily') return 4;
44	  if (frequency === 'weekly') return 4;
45	  throw new Error(`no anchor hour for ${frequency}`);
46	}
47	
48	export function periodMs(frequency) {
49	  if (frequency === 'hourly') return HOUR;
50	  if (frequency === 'weekly') return 7 * DAY;
51	  return DAY; // daily, daily-Nh
52	}
53	
54	export function mostRecentAnchor(frequency, now) {
55	  if (frequency === 'manual') return null;
56	  if (frequency === 'hourly') return Math.floor(now / HOUR) * HOUR;
57	  const d = new Date(now);
58	  let a = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), anchorHour(frequency));
59	  if (a > now) a -= DAY;
60	  if (frequency === 'weekly') {
61	    while (new Date(a).getUTCDay() !== 0 || a > now) a -= DAY;
62	  }
63	  return a;
64	}
65	
66	export function nextAnchor(frequency, now) {
67	  let a = mostRecentAnchor(frequency, now);
68	  do a += periodMs(frequency); while (a <= now);
69	  return a;
70	}
71	
72	// ---- the simulator ----------------------------------------------------------
73	
74	export function makeSim({
75	  tasks,
76	  afterMode = 'yield', // 'yield' (the design) | 'blocked-by' (S24's rejected wiring)
77	  tickMinute = 17,
78	  executingLeashMs = 1 * HOUR,
79	  agentLeashMs = 3 * HOUR,
80	  heartbeatMinutes = 15, // the executor's activity comment cadence during the work step
81	  maxItems = 1, // items one executor run settles before re-dispatching a fresh run
82	                // (owner, 2026-08-15: one run, one item — the run's timeout sizes to
83	                // one work bound, and self-re-dispatch chains the rest)
84	  staleReadyPeriods = 2,
85	  staleBlockedMs = 2 * DAY,
86	  heartbeatsDisabled = false, // S31b only: demonstrate the livelock heartbeats prevent
87	} = {}) {
88	  const registry = new Map(tasks.map((t) => [t.id, t]));
89	  const titleOf = (id) => `[claudinite-work] ${id}`;
90	
91	  // F17, reframed by the work-as-work review (2026-08-15): the leash no longer
92	  // has to exceed every task's work bound — heartbeat comments during the work
93	  // step keep a LIVE executor's item out of the reclaim, however long the work
94	  // runs, so the leash measures executor death, not work duration. The wiring
95	  // constraint that remains is the one the heartbeat itself needs: the
96	  // heartbeat interval must sit well inside the leash, or every heartbeat
97	  // arrives too late to matter.
98	  if (heartbeatMinutes * MIN >= executingLeashMs) {
99	    throw new Error(
100	      `heartbeat interval (${heartbeatMinutes}m) reaches the executing leash — F17 (reframed)`);
101	  }
102	
103	  const issues = []; // {number,title,taskId,origin,labels:Set,state,createdAt,closedAt,readySince,lastActivity,notBefore,blockedBy:[],outcome,rolls:[],comments:[],escalated,sessions:[],quarantined}
104	  const log = []; // {t,kind,task,issue,...}
105	  const world = {}; // scenario-owned signal state, read by precondition fns
106	  const queue = []; // {t,seq,fn}
107	  let seq = 0;
108	  let now = 0;
109	  let sessionSeq = 0;
110	  const crashNextOf = new Set(); // taskIds whose next execution dies mid-claim
111	  const crashDuringWorkOf = new Map(); // taskId -> minutes into the work step the runner dies
112	  const crashAgentOf = new Set(); // taskIds whose next agent session dies mid-run
113	
114	  const schedule = (t, fn) => queue.push({ t, seq: seq++, fn });
115	  const record = (kind, extra) => log.push({ t: now, at: iso(now), kind, ...extra });
116	
117	  const open = () => issues.filter((i) => i.state === 'open');
118	  const has = (i, l) => i.labels.has(l);
119	  const family = (taskId) =>
120	    issues.filter((i) => i.title === titleOf(taskId) && i.origin === 'schedule');
121	  const standingItem = (taskId) => family(taskId).find((i) => i.state === 'open');
122	
123	  function createIssue({ taskId, origin, labels, notBefore = null, blockedBy = [], urgent = false, qualifier = null }) {
124	    const it = {
125	      number: issues.length + 900,
126	      title: titleOf(taskId) + (qualifier ? ` ${qualifier}` : ''),
127	      taskId, origin,
128	      labels: new Set(labels.concat(urgent ? ['task:urgent'] : [])),
129	      state: 'open',
130	      createdAt: now, closedAt: null,
131	      readySince: labels.includes('task:ready') ? now : null,
132	      lastActivity: now,
133	      notBefore, blockedBy,
134	      outcome: null, rolls: [], comments: [], escalated: false,
135	      sessions: [], quarantined: false,
136	    };
137	    issues.push(it);
138	    record('create', { task: taskId, issue: it.number, origin });
139	    return it;
140	  }
141	
142	  function swap(it, from, to) {
143	    it.labels.delete(from);
144	    it.labels.add(to);
145	    it.readySince = to === 'task:ready' ? now : null;
146	    // F18: every transition INTO ready opens a new claim episode — claim
147	    // comments from a previous tenure are dead and must not outrank a live
148	    // claimant (the revert/reclaim comment is the episode boundary)
149	    if (to === 'task:ready') it.claimEpoch = seq++;
150	    it.lastActivity = now;
151	  }
152	
153	  function close(it, outcome) {
154	    it.state = 'closed';
155	    it.closedAt = now;
156	    it.outcome = outcome;
157	    for (const l of [...it.labels]) if (l.startsWith('task:')) it.labels.delete(l);
158	    record('close', { task: it.taskId, issue: it.number, outcome });
159	    // F1, reopened 2026-08-15: whoever closes an item — executor or agent —
160	    // also re-checks blocked items' readiness in code (Blocked-by all closed,
161	    // Not-before passed) and a drain follows, so chain links proceed in
162	    // minutes instead of waiting out the tick. The tick's readiness job stays

