  const tasks = [
    { id: 'x/slow', frequency: 'daily', outcome: 'done', preworkMinutes: 30,
      precondition: () => ({ run: true }) },
    { id: 'x/quick', frequency: 'daily', outcome: 'done', preworkMinutes: 3,
      precondition: () => ({ run: true }) },
  ];
